import {stem} from './core.js';
const $=id=>document.getElementById(id);
export function officeOptions(){return '<h3>Word, Excel y PowerPoint a PDF</h3><p>Conversión local con LibreOffice. Conserva mejor tablas, imágenes y estilos que una extracción de texto.</p><p class="hint">Disponible desde el paquete de Windows o Mac, con <a href="https://www.libreoffice.org/download/download-libreoffice/" target="_blank" rel="noopener noreferrer">LibreOffice instalado</a>. No requiere cuenta ni API. La web y el móvil no ejecutan este motor: usa Exportar a PDF en tu aplicación de Office o el paquete de escritorio.</p><p id="office-status" class="hint" role="status">Comprobando la instalación…</p><button id="office-check" class="text-button" type="button">Comprobar instalación</button><p class="hint">DOCX, XLSX y PPTX · hasta 25 MB · sin contraseña, macros, objetos incrustados o datos externos. Usa los ajustes de página y áreas de impresión guardados en Office. Puede cambiar el diseño si faltan fuentes; revisa el PDF antes de compartirlo. Se crean archivos temporales en este ordenador y se eliminan al terminar.</p>';}
function endpoint(action){if(location.hostname!=='127.0.0.1')throw Object.assign(new Error('Esta conversión necesita el paquete de escritorio para Windows o Mac y LibreOffice instalado.'),{code:'OFFICE_DESKTOP'});return new URL('./_desktop/office/'+action,location.href);}
export function bindOffice(){const check=async()=>{const status=$('office-status'),button=$('office-check');button.disabled=true;try{const r=await fetch(endpoint('status'),{headers:{'X-PDF-Local':'1'},cache:'no-store',signal:AbortSignal.timeout(5000)});if(!r.ok)throw new Error('Actualiza el paquete de escritorio para utilizar Office a PDF.');const value=await r.json();status.textContent=value.available?'LibreOffice detectado. Selecciona tu archivo y pulsa Convertir a PDF.':'No se ha encontrado LibreOffice. Instálalo y vuelve a comprobar.';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};$('office-check').onclick=check;check();}
export async function officeToPDF(file,progress=()=>{}){progress(.2,'Convirtiendo con LibreOffice en tu ordenador…');let response;try{response=await fetch(endpoint('convert'),{method:'POST',headers:{'Content-Type':'application/octet-stream','X-PDF-Local':'1','X-PDF-Extension':file.name.split('.').pop().toLowerCase()},body:file.bytes,signal:AbortSignal.timeout(110000)});}catch(e){if(e.code==='OFFICE_DESKTOP')throw e;throw new Error('No se pudo contactar con el motor local. Comprueba que PDF sigue abierto.');}if(!response.ok){let detail;try{detail=await response.json();}catch{}throw Object.assign(new Error(detail?.error||'No se pudo convertir el documento.'),{code:detail?.code||'OFFICE_CONVERT'});}const bytes=new Uint8Array(await response.arrayBuffer());if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw new Error('El motor no devolvió un PDF válido.');return [{bytes,name:stem(file.name)+'.pdf',type:'application/pdf',note:'Convertido localmente con LibreOffice. Revisa páginas, tablas, fuentes y áreas de impresión antes de descargar o compartir.'}];}
